     1→import { NextRequest, NextResponse } from 'next/server';
     2→import getDb from '@/lib/db';
     3→import type { SubmissionInput, SubmissionRow } from '@/lib/types';
     4→import * as XLSX from 'xlsx';
     5→
     6→export async function POST(request: NextRequest) {
     7→  const db = getDb();
     8→  let body: SubmissionInput;
     9→
    10→  try {
    11→    body = await request.json();
    12→  } catch {
    13→    return NextResponse.json({ error: '잘못된 요청 형식입니다.' }, { status: 400 });
    14→  }
    15→
    16→  const { department_name, dean_name, submitted_at, department_plan, candidates, hiringProgress } = body;
    17→
    18→  if (!department_name || !dean_name || !submitted_at) {
    19→    return NextResponse.json(
    20→      { error: '필수 필드가 누락되었습니다. (department_name, dean_name, submitted_at)' },
    21→      { status: 400 }
    22→    );
    23→  }
    24→
    25→  if (!candidates || candidates.length === 0) {
    26→    return NextResponse.json(
    27→      { error: '최소 1명 이상의 후보자를 추가해야 합니다.' },
    28→      { status: 400 }
    29→    );
    30→  }
    31→
    32→  try {
    33→    const insertSubmission = db.prepare(
    34→      `INSERT INTO submissions (department_name, dean_name, submitted_at, department_plan) VALUES (?, ?, ?, ?)`
    35→    );
    36→    const insertCandidate = db.prepare(
    37→      `INSERT INTO candidates (submission_id, name, birth_year, current_affiliation, current_position, major_field, total_papers, jcr_ratio, fwci, remarks)
    38→       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    39→    );
    40→    const insertDegree = db.prepare(
    41→      `INSERT INTO candidate_degrees (candidate_id, school, major, degree_year, degree_type)
    42→       VALUES (?, ?, ?, ?, ?)`
    43→    );
    44→    const insertCareer = db.prepare(
    45→      `INSERT INTO candidate_careers (candidate_id, institution, position, period)
    46→       VALUES (?, ?, ?, ?)`
    47→    );
    48→    const insertProgress = db.prepare(
    49→      `INSERT INTO hiring_progress (submission_id, progress_date, content, person_in_charge)
    50→       VALUES (?, ?, ?, ?)`
    51→    );
    52→
    53→    const runTransaction = db.transaction(() => {
    54→      const submissionResult = insertSubmission.run(department_name, dean_name, submitted_at, department_plan ?? null);
    55→      const submissionId = Number(submissionResult.lastInsertRowid);
    56→
    57→      for (const candidate of candidates ?? []) {
    58→        if (!candidate.name) continue;
    59→        const candidateResult = insertCandidate.run(
    60→          submissionId,
    61→          candidate.name,
    62→          candidate.birth_year ?? null,
    63→          candidate.current_affiliation ?? null,
    64→          candidate.current_position ?? null,
    65→          candidate.major_field ?? null,
    66→          candidate.total_papers ?? null,
    67→          candidate.jcr_ratio ?? null,
    68→          candidate.fwci ?? null,
    69→          candidate.remarks ?? null
    70→        );
    71→        const candidateId = Number(candidateResult.lastInsertRowid);
    72→
    73→        for (const degree of candidate.degrees ?? []) {
    74→          insertDegree.run(
    75→            candidateId,
    76→            degree.school ?? null,
    77→            degree.major ?? null,
    78→            degree.degree_year ?? null,
    79→            degree.degree_type ?? null
    80→          );
    81→        }
    82→
    83→        for (const career of candidate.careers ?? []) {
    84→          insertCareer.run(
    85→            candidateId,
    86→            career.institution ?? null,
    87→            career.position ?? null,
    88→            career.period ?? null
    89→          );
    90→        }
    91→      }
    92→
    93→      for (const progress of hiringProgress ?? []) {
    94→        insertProgress.run(
    95→          submissionId,
    96→          progress.progress_date ?? null,
    97→          progress.content ?? null,
    98→          progress.person_in_charge ?? null
    99→        );
   100→      }
   101→
   102→      return submissionId;
   103→    });
   104→
   105→    const id = runTransaction();
   106→
   107→    return NextResponse.json({ id, message: '제출 완료' }, { status: 201 });
   108→  } catch (error) {
   109→    console.error('POST /api/submissions error:', error);
   110→    return NextResponse.json(
   111→      { error: '서버 오류가 발생했습니다.' },
   112→      { status: 500 }
   113→    );
   114→  }
   115→}
