   117→export async function GET(request: NextRequest) {
   118→  const db = getDb();
   119→  const { searchParams } = new URL(request.url);
   120→  const format = searchParams.get('format');
   121→
   122→  try {
   123→    const rows = db
   124→      .prepare(
   125→        `SELECT s.*, COUNT(c.id) as candidate_count
   126→         FROM submissions s
   127→         LEFT JOIN candidates c ON c.submission_id = s.id
   128→         GROUP BY s.id
   129→         ORDER BY s.created_at DESC`
   130→      )
   131→      .all() as SubmissionRow[];
   132→
   133→    if (format === 'excel') {
   134→      type CandidateExcelRow = {
   135→        id: number; submission_id: number; department_name: string;
   136→        dean_name: string; submitted_at: string; name: string;
   137→        birth_year?: number; current_affiliation?: string; current_position?: string;
   138→        major_field?: string; total_papers?: number; jcr_ratio?: number;
   139→        fwci?: number; remarks?: string;
   140→      };
   141→      type DegreeExcelRow = {
   142→        candidate_id: number; candidate_name: string; department_name: string;
   143→        school?: string; major?: string; degree_year?: number; degree_type?: string;
   144→      };
   145→      type CareerExcelRow = {
   146→        candidate_id: number; candidate_name: string; department_name: string;
   147→        institution?: string; position?: string; period?: string;
   148→      };
   149→
   150→      const candidateRows = db
   151→        .prepare(
   152→          `SELECT c.*, s.department_name, s.dean_name, s.submitted_at
   153→           FROM candidates c
   154→           JOIN submissions s ON s.id = c.submission_id
   155→           ORDER BY s.id, c.id`
   156→        )
   157→        .all() as CandidateExcelRow[];
   158→
   159→      const degreeRows = db
   160→        .prepare(
   161→          `SELECT cd.*, c.name as candidate_name, s.department_name
   162→           FROM candidate_degrees cd
   163→           JOIN candidates c ON c.id = cd.candidate_id
   164→           JOIN submissions s ON s.id = c.submission_id
   165→           ORDER BY s.id, c.id, cd.id`
   166→        )
   167→        .all() as DegreeExcelRow[];
   168→
   169→      const careerRows = db
   170→        .prepare(
   171→          `SELECT ca.*, c.name as candidate_name, s.department_name
   172→           FROM candidate_careers ca
   173→           JOIN candidates c ON c.id = ca.candidate_id
   174→           JOIN submissions s ON s.id = c.submission_id
   175→           ORDER BY s.id, c.id, ca.id`
   176→        )
   177→        .all() as CareerExcelRow[];
   178→
   179→      const wb = XLSX.utils.book_new();
   180→
   181→      const sheet1Data = rows.map((r) => ({
   182→        ID: r.id,
   183→        학과명: r.department_name,
   184→        학장명: r.dean_name,
   185→        제출일시: r.submitted_at,
   186→        학과발전계획: r.department_plan ?? '',
   187→        상태: r.status,
   188→        후보자수: r.candidate_count ?? 0,
   189→        생성일시: r.created_at,
   190→      }));
   191→      const ws1 = XLSX.utils.json_to_sheet(sheet1Data);
   192→      XLSX.utils.book_append_sheet(wb, ws1, '제출목록');
   193→
   194→      const sheet2Data = candidateRows.map((c) => ({
   195→        후보자ID: c.id,
   196→        제출ID: c.submission_id,
   197→        학과명: c.department_name,
   198→        학장명: c.dean_name,
   199→        제출일시: c.submitted_at,
   200→        이름: c.name,
   201→        출생연도: c.birth_year,
   202→        현소속: c.current_affiliation,
   203→        현직위: c.current_position,
   204→        전공분야: c.major_field,
   205→        총논문수: c.total_papers,
   206→        JCR비율: c.jcr_ratio,
   207→        FWCI: c.fwci,
   208→        비고: c.remarks,
   209→      }));
   210→      const ws2 = XLSX.utils.json_to_sheet(sheet2Data);
   211→      XLSX.utils.book_append_sheet(wb, ws2, '후보자목록');
   212→
   213→      const sheet3Data = degreeRows.map((d) => ({
   214→        학과명: d.department_name,
   215→        후보자명: d.candidate_name,
   216→        학교명: d.school,
   217→        전공: d.major,
   218→        취득년도: d.degree_year,
   219→        학위구분: d.degree_type,
   220→      }));
   221→      const ws3 = XLSX.utils.json_to_sheet(sheet3Data);
   222→      XLSX.utils.book_append_sheet(wb, ws3, '학위목록');
   223→
   224→      const sheet4Data = careerRows.map((ca) => ({
   225→        학과명: ca.department_name,
   226→        후보자명: ca.candidate_name,
   227→        기관명: ca.institution,
   228→        직위: ca.position,
   229→        기간: ca.period,
   230→      }));
   231→      const ws4 = XLSX.utils.json_to_sheet(sheet4Data);
   232→      XLSX.utils.book_append_sheet(wb, ws4, '경력목록');
   233→
   234→      const buffer = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
   235→
   236→      return new NextResponse(buffer, {
   237→        status: 200,
   238→        headers: {
   239→          'Content-Type':
   240→            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
   241→          'Content-Disposition': 'attachment; filename="submissions.xlsx"',
   242→        },
   243→      });
   244→    }
   245→
   246→    return NextResponse.json(rows);
   247→  } catch (error) {
   248→    console.error('GET /api/submissions error:', error);
   249→    return NextResponse.json(
   250→      { error: '서버 오류가 발생했습니다.' },
   251→      { status: 500 }
   252→    );
   253→  }
   254→}
