     1→import { NextRequest, NextResponse } from 'next/server';
     2→import getDb from '@/lib/db';
     3→import type {
     4→  SubmissionDetail,
     5→  SubmissionRow,
     6→  CandidateDbRow,
     7→  DegreeDbRow,
     8→  CareerDbRow,
     9→  ProgressDbRow,
    10→} from '@/lib/types';
    11→
    12→interface Params {
    13→  params: { id: string };
    14→}
    15→
    16→export async function GET(_request: NextRequest, { params }: Params) {
    17→  const db = getDb();
    18→  const id = parseInt(params.id, 10);
    19→
    20→  if (isNaN(id)) {
    21→    return NextResponse.json({ error: '유효하지 않은 ID입니다.' }, { status: 400 });
    22→  }
    23→
    24→  try {
    25→    const submission = db
    26→      .prepare(`SELECT * FROM submissions WHERE id = ?`)
    27→      .get(id) as SubmissionRow | undefined;
    28→
    29→    if (!submission) {
    30→      return NextResponse.json({ error: '해당 제출 데이터를 찾을 수 없습니다.' }, { status: 404 });
    31→    }
    32→
    33→    const candidateRows = db
    34→      .prepare(`SELECT * FROM candidates WHERE submission_id = ? ORDER BY id`)
    35→      .all(id) as CandidateDbRow[];
    36→
    37→    let candidates: SubmissionDetail['candidates'] = [];
    38→
    39→    if (candidateRows.length > 0) {
    40→      const candidateIds = candidateRows.map((c) => c.id);
    41→      const inClause = candidateIds.map(() => '?').join(',');
    42→
    43→      const allDegrees = db
    44→        .prepare(`SELECT * FROM candidate_degrees WHERE candidate_id IN (${inClause}) ORDER BY candidate_id, id`)
    45→        .all(...candidateIds) as DegreeDbRow[];
    46→
    47→      const allCareers = db
    48→        .prepare(`SELECT * FROM candidate_careers WHERE candidate_id IN (${inClause}) ORDER BY candidate_id, id`)
    49→        .all(...candidateIds) as CareerDbRow[];
    50→
    51→      const degreesByCandidate = new Map<number, DegreeDbRow[]>();
    52→      const careersByCandidate = new Map<number, CareerDbRow[]>();
    53→
    54→      for (const d of allDegrees) {
    55→        const list = degreesByCandidate.get(d.candidate_id) ?? [];
    56→        list.push(d);
    57→        degreesByCandidate.set(d.candidate_id, list);
    58→      }
    59→      for (const ca of allCareers) {
    60→        const list = careersByCandidate.get(ca.candidate_id) ?? [];
    61→        list.push(ca);
    62→        careersByCandidate.set(ca.candidate_id, list);
    63→      }
    64→
    65→      candidates = candidateRows.map((c) => ({
    66→        id: c.id,
    67→        name: c.name,
    68→        birth_year: c.birth_year,
    69→        current_affiliation: c.current_affiliation,
    70→        current_position: c.current_position,
    71→        major_field: c.major_field,
    72→        total_papers: c.total_papers,
    73→        jcr_ratio: c.jcr_ratio,
    74→        fwci: c.fwci,
    75→        remarks: c.remarks,
    76→        degrees: (degreesByCandidate.get(c.id) ?? []).map((d) => ({
    77→          school: d.school,
    78→          major: d.major,
    79→          degree_year: d.degree_year,
    80→          degree_type: d.degree_type,
    81→        })),
    82→        careers: (careersByCandidate.get(c.id) ?? []).map((ca) => ({
    83→          institution: ca.institution,
    84→          position: ca.position,
    85→          period: ca.period,
    86→        })),
    87→      }));
    88→    }
    89→
    90→    const hiringProgress = (
    91→      db
    92→        .prepare(`SELECT * FROM hiring_progress WHERE submission_id = ? ORDER BY id`)
    93→        .all(id) as ProgressDbRow[]
    94→    ).map((p) => ({
    95→      progress_date: p.progress_date,
    96→      content: p.content,
    97→      person_in_charge: p.person_in_charge,
    98→    }));
    99→
   100→    const detail: SubmissionDetail = {
   101→      ...submission,
   102→      candidates,
   103→      hiringProgress,
   104→    };
   105→
   106→    return NextResponse.json(detail);
   107→  } catch (error) {
   108→    console.error(`GET /api/submissions/${id} error:`, error);
   109→    return NextResponse.json(
   110→      { error: '서버 오류가 발생했습니다.' },
   111→      { status: 500 }
   112→    );
   113→  }
   114→}
