   142→
   143→  const updateDegree = (candidateId: string, degreeId: string, key: keyof DegreeRow, value: string) => {
   144→    updateCandidateNested(candidateId, (c) => ({
   145→      ...c,
   146→      degrees: c.degrees.map((d) => (d._id === degreeId ? { ...d, [key]: value } : d)),
   147→    }));
   148→  };
