   165→    }));
   166→  };
   167→
   168→  const updateCareer = (candidateId: string, careerId: string, key: keyof CareerRow, value: string) => {
   169→    updateCandidateNested(candidateId, (c) => ({
   170→      ...c,
   171→      careers: c.careers.map((ca) => (ca._id === careerId ? { ...ca, [key]: value } : ca)),
   172→    }));
   173→  };
