   183→          onAddRow={addCandidate}
   184→          onDeleteRow={deleteCandidate}
   185→          onUpdateRow={(id, key, value) => updateCandidate(id, key as keyof CandidateRow, value)}
   186→          addLabel="+ 후보자 추가"
   187→          emptyMessage="후보자가 없습니다. 후보자를 추가해주세요."
   188→        />
   189→      </div>
   190→
   191→      {/* 학위 및 경력 사항 섹션 */}
   192→      {candidates.length > 0 && (
   193→        <div className="section-card">
