     5→export interface ColumnDef<T> {
     6→  key: keyof T;
     7→  label: string;
     8→  type: 'text' | 'number' | 'date' | 'select';
     9→  options?: string[];
    10→  width?: string;
    11→}
    12→
    13→interface DynamicTableProps<T extends { _id: string }> {
    14→  columns: ColumnDef<T>[];
    15→  rows: T[];
    16→  onAddRow: () => void;
    17→  onDeleteRow: (id: string) => void;
    18→  onUpdateRow: (id: string, key: keyof T, value: string) => void;
    19→  addLabel?: string;
    20→  emptyMessage?: string;
    21→}
    22→
    23→export default function DynamicTable<T extends { _id: string }>({
    24→  columns,
    25→  rows,
    26→  onAddRow,
    27→  onDeleteRow,
    28→  onUpdateRow,
    29→  addLabel = '+ 행 추가',
    30→  emptyMessage = '데이터가 없습니다. 행을 추가해주세요.',
    31→}: DynamicTableProps<T>) {
    32→  return (
    33→    <div className="w-full">
    34→      <div className="overflow-x-auto rounded-lg border border-gray-200">
    35→        <table className="min-w-full divide-y divide-gray-200">
    36→          <thead className="bg-blue-700">
    37→            <tr>
    38→              {columns.map((col) => (
    39→                <th
    40→                  key={String(col.key)}
    41→                  className="px-3 py-3 text-left text-xs font-semibold text-white uppercase tracking-wider whitespace-nowrap"
    42→                  style={col.width ? { width: col.width } : {}}
    43→                >
    44→                  {col.label}
    45→                </th>
    46→              ))}
    47→              <th className="px-3 py-3 text-center text-xs font-semibold text-white uppercase tracking-wider w-14">
    48→                삭제
    49→              </th>
    50→            </tr>
    51→          </thead>
    52→          <tbody className="bg-white divide-y divide-gray-100">
    53→            {rows.length === 0 ? (
    54→              <tr>
    55→                <td
    56→                  colSpan={columns.length + 1}
    57→                  className="px-4 py-6 text-center text-gray-400 text-sm"
    58→                >
    59→                  {emptyMessage}
    60→                </td>
    61→              </tr>
    62→            ) : (
    63→              rows.map((row, rowIndex) => (
    64→                <tr
    65→                  key={row._id}
    66→                  className={rowIndex % 2 === 0 ? 'bg-white' : 'bg-gray-50'}
    67→                >
    68→                  {columns.map((col) => (
    69→                    <td key={String(col.key)} className="px-2 py-1.5">
    70→                      {col.type === 'select' && col.options ? (
    71→                        <select
    72→                          value={String(row[col.key] ?? '')}
    73→                          onChange={(e) =>
    74→                            onUpdateRow(row._id, col.key, e.target.value)
    75→                          }
    76→                          className="input-cell"
    77→                        >
    78→                          <option value="">선택</option>
    79→                          {col.options.map((opt) => (
    80→                            <option key={opt} value={opt}>
    81→                              {opt}
    82→                            </option>
    83→                          ))}
    84→                        </select>
    85→                      ) : (
    86→                        <input
    87→                          type={col.type === 'number' ? 'text' : col.type}
    88→                          value={String(row[col.key] ?? '')}
    89→                          onChange={(e) =>
    90→                            onUpdateRow(row._id, col.key, e.target.value)
    91→                          }
    92→                          className="input-cell"
    93→                          placeholder={col.label}
    94→                        />
    95→                      )}
    96→                    </td>
    97→                  ))}
    98→                  <td className="px-2 py-1.5 text-center">
    99→                    <button
   100→                      type="button"
   101→                      onClick={() => onDeleteRow(row._id)}
   102→                      className="btn-danger"
   103→                      title="행 삭제"
   104→                    >
   105→                      ✕
   106→                    </button>
   107→                  </td>
   108→                </tr>
   109→              ))
   110→            )}
   111→          </tbody>
   112→        </table>
   113→      </div>
   114→      <div className="mt-3">
   115→        <button
   116→          type="button"
   117→          onClick={onAddRow}
   118→          className="btn-secondary text-sm py-1.5 px-3"
   119→        >
   120→          {addLabel}
   121→        </button>
   122→      </div>
   123→    </div>
   124→  );
   125→}
